<?php
/** Content-language integration. Disposable CI WordPress only. */
require __DIR__.'/m0/bootstrap.php';
require_once EIPSI_FORMS_PLUGIN_DIR.'includes/study-engine/builder.php';
require_once EIPSI_FORMS_PLUGIN_DIR.'includes/assessment-editor/runtime/Owner.php';
require_once EIPSI_FORMS_PLUGIN_DIR.'includes/assessment-editor/Portable.php';
require_once EIPSI_FORMS_PLUGIN_DIR.'includes/study-engine/runtime/PublicPage.php';
use EIPSI\I18n\ContentDefaults as C;
use EIPSI\AssessmentEditor as A;
use EIPSI\StudyEngine\Builder as B;
use EIPSI\StudyEngine\Longitudinal as L;
use EIPSI\StudyEngine\Runtime\PublicMessages as M;
$savedLanguage=get_option('eipsi_forms_language',null);$tests=0;$failures=0;$original=get_current_user_id();$ids=array();$studies=array();$assessments=array();$versions=array();$owner=new A\Runtime\Owner();$library=get_option(B\EmailLibrary::OPTION,null);$enabled=get_option('eipsi_native_runtime_enabled',null);
function ic_test($name,$fn){global $tests,$failures;$tests++;try{$fn();echo "PASS $name\n";}catch(Throwable $e){$failures++;echo 'FAIL '.$name.': '.$e->getMessage()."\n";}}
function ic_assert($v,$message='Content contract failed'){if(!$v)throw new RuntimeException($message);}
function ic_same($a,$b){return EIPSI\StudyEngine\Contracts\Canonical::json($a)===EIPSI\StudyEngine\Contracts\Canonical::json($b);}
function ic_definition($language){$d=json_decode(file_get_contents(__DIR__.'/assessment-editor/functional-fixture.json'),true);$d['id']='AE_IC_'.bin2hex(random_bytes(8));$d['content_language']=$language;$d['title']=$language==='en'?'Custom English assessment':'Evaluación propia';$d['elements']=array($d['elements'][0]);$d['flow']=A\Flow::defaults($language);return A\Definition::validate($d);}
try{
foreach(array('en','es') as $language){$id=wp_create_user('i18nc_'.bin2hex(random_bytes(5)),wp_generate_password());if(is_wp_error($id))throw new RuntimeException($id->get_error_message());(new WP_User($id))->set_role('administrator');$ids[$language]=$id;}
$service=new B\Service(new EIPSI\StudyEngine\Persistence\Database($wpdb));
foreach(array('en','es') as $language){
update_option('eipsi_forms_language',$language,false);wp_set_current_user($ids[$language]);
ic_test($language.' Study creation inherits actual creator preference',function()use($service,$language,&$studies){$s=$service->create(array('name'=>'Content test '.$language),'IC_'.bin2hex(random_bytes(8)));$studies[]=$s;ic_assert($s['definition']['protocol_metadata']['content_language']===$language);ic_assert(ic_same($s['definition']['protocol_metadata']['public_messages'],C::get('public_messages',$language)));});
ic_test($language.' Assessment persistence materializes validation and Flow',function()use($language,&$assessments){$r=A\Repository::save(ic_definition($language),0);$assessments[]=$r;ic_assert($r['definition']['elements'][0]['properties']['required_message']===C::get('question_messages',$language)['required_message']);ic_assert($r['definition']['flow']['messages']===C::get('flow_messages',$language));});
ic_test($language.' InitialScreen validates all materialized defaults',function()use($language){$c=L\InitialScreen::defaults($language);$normalized=L\InitialScreen::normalize($c);$expected=$c;foreach($expected['templates'] as &$t)$t=L\InitialScreen::template($t);unset($t);ic_assert(ic_same($normalized,$expected),'Initial content changed beyond existing sanitizer');ic_assert($c['withdrawal']['confirmation']===C::get('confirmation',$language));ic_assert($c['templates']===L\EmailTemplate::defaults($language));});
ic_test($language.' public document lang comes from object not site locale',function()use($language){$html=EIPSI\StudyEngine\Runtime\PublicPage::document('<main>authored</main>','Title',array(),array(),$language);ic_assert(strpos($html,'<html lang="'.$language.'">')!==false);});
ic_test($language.' three emails preserve all six tokens and HTML sanitization',function()use($language){foreach(L\EmailTemplate::defaults($language) as $purpose=>$t){foreach(array_keys(L\InitialScreen::VARIABLES) as $token)ic_assert(strpos($t['html'],'['.$token.']')!==false);$values=array_fill_keys(array_keys(L\InitialScreen::VARIABLES),'<script>unsafe</script>');$render=(new L\EmailTemplate())->render($purpose,$values,array(),$language);ic_assert(strpos($render['html'],'<script>')===false);ic_assert(strpos($render['html'],'[direct_link]')===false);}});
ic_test($language.' standalone library creation inherits creator language',function()use($language){$doc=B\EmailLibrary::read();ic_assert($doc['defaults']===array_map(function($t){$t['from_name']=B\EmailLibrary::read()['defaults']['VERIFY_PARTICIPANT']['from_name'];return $t;},L\EmailTemplate::defaults($language)));$entry=L\EmailTemplate::defaults($language)['VERIFY_PARTICIPANT']+array('name'=>'Library '.$language,'purpose'=>'VERIFY_PARTICIPANT');$saved=B\EmailLibrary::save($entry,$doc['revision']);$t=end($saved['templates']);ic_assert($t['content_language']===$language);ic_assert($t['html']===L\InitialScreen::template(array_intersect_key($entry,array_flip(array('subject','html'))))['html']);});
}
ic_test('Cross-user reads keep Assessment and Study hashes identical',function()use($ids,$service,$studies,$assessments){foreach($ids as $id){wp_set_current_user($id);foreach($assessments as $r)ic_assert(A\Definition::json(A\Repository::load($r['definition']['id'])['definition'])===A\Definition::json($r['definition']));foreach($studies as $s)ic_assert(EIPSI\StudyEngine\Contracts\Canonical::protocolHash($service->load($s['id'])['definition'])===EIPSI\StudyEngine\Contracts\Canonical::protocolHash($s['definition']));}});
ic_test('Changing content language retains all existing authored strings',function()use($assessments){$d=$assessments[0]['definition'];$before=$d;unset($before['content_language']);$d['content_language']='es';$d=A\Definition::validate($d);unset($d['content_language']);ic_assert(A\Definition::json($d)===A\Definition::json($before));});
ic_test('Publication fixes content independently of later draft and admin changes',function()use($owner,$assessments,&$versions,$ids){$r=$assessments[0];$v=$owner->publish($r['definition']['id'],$r['revision']);$versions[]=$v;$before=$owner->store->find('versions',$v['version_id']);$d=$r['definition'];$d['content_language']='es';$d['title']='Draft changed';A\Repository::save($d,$r['revision']);wp_set_current_user($ids['es']);$after=A\Repository::loadVersion($r['definition']['id'],$v['version_id']);ic_assert($after['definition']['content_language']==='en');ic_assert(hash('sha256',$before['definition_json'])===$after['version']['definition_hash']);});
ic_test('Portable assessment retains language, content and tokens while renewing import identities',function()use($assessments){$d=$assessments[1]['definition'];$document=A\Portable::export($d['id'],1);$import=A\Portable::import(A\Definition::json($document));$GLOBALS['assessments'][]=$import;ic_assert($import['definition']['content_language']==='es');ic_assert($import['definition']['flow']===$d['flow'] || $import['definition']['flow']['messages']===$d['flow']['messages']);ic_assert($import['definition']['id']!==$d['id']);ic_assert(ic_same($import['definition']['elements'][0]['properties'],$d['elements'][0]['properties']));});
ic_test('Existing missing language remains Spanish and does not acquire the field',function(){$d=ic_definition('en');unset($d['content_language']);$before=A\Definition::json($d);ic_assert(C::language($d)==='es');ic_assert(A\Definition::json(A\Definition::validate($d))===$before);});
ic_test('Invalid declared language is rejected by all authoring validators',function()use($service,$studies){foreach(array('fr','en_US','',null,1) as $bad){$d=ic_definition('en');$d['content_language']=$bad;$rejected=false;try{A\Definition::validate($d);}catch(InvalidArgumentException $e){$rejected=true;}ic_assert($rejected);$d=$studies[0]['definition'];$d['protocol_metadata']['content_language']=$bad;$rejected=false;try{B\Draft::validate($d);}catch(InvalidArgumentException $e){$rejected=true;}ic_assert($rejected);}});
ic_test('English Study and Spanish Assessment keep independent public messages',function()use($assessments,$studies){ic_assert($assessments[1]['definition']['flow']['completion']['title']==='Gracias por responder');ic_assert(M::text($studies[0]['definition'],'paused_body')==='The study is paused.');});
ic_test('Worker email resolution ignores current administrator and WordPress locale',function()use($ids){$values=array_fill_keys(array_keys(L\InitialScreen::VARIABLES),'authored');$expected=null;foreach($ids as $language=>$id){update_option('eipsi_forms_language',$language,false);wp_set_current_user($id);$result=(new L\EmailTemplate())->render('ASSESSMENT_AVAILABLE',$values,L\InitialScreen::defaults('en')['templates'],'en');if($expected===null)$expected=$result;ic_assert($expected===$result);ic_assert($result['subject']==='Assessment available');}});
ic_test('Missing withdrawal completion uses declared content context and explicit empty remains empty',function(){foreach(array('en','es') as $language){$w=C::get('initial',$language)['withdrawal'];unset($w['completion_html']);$html=L\InitialScreen::withdrawalCompletion($w,'RETAIN_FOR_ANALYSIS',$language);ic_assert(strpos($html,$language==='en'?'Your participation has ended':'Tu participación terminó')!==false);$w['completion_html']='';ic_assert(L\InitialScreen::withdrawalCompletion($w,'RETAIN_FOR_ANALYSIS',$language)==='');
$definition=L\Configuration::apply(array('protocol_metadata'=>array('content_language'=>$language)));unset($definition['protocol_metadata']['longitudinal']['initial_screen']);
$frame=array('definition'=>$definition,'study'=>array('public_id'=>'I18ND_FALLBACK'),'entry'=>true,'csrf'=>'fixture','view'=>array('revision'=>0));$screen=(new L\EmailTemplate())->screen($frame);ic_assert(preg_match('/<button[^>]*value="enroll"[^>]*>'.($language==='en'?'Continue':'Continuar').'<\/button>/', $screen)===1);
$c=L\InitialScreen::defaults($language);unset($c['withdrawal']['confirmation'],$c['withdrawal']['back_label']);$frame['definition']['protocol_metadata']['longitudinal']['initial_screen']=$c;$screen=(new L\EmailTemplate())->screen($frame);ic_assert(preg_match('/<button[^>]*data-close-withdrawal[^>]*>'.($language==='en'?'Back':'Volver').'<\/button>/', $screen)===1);ic_assert(preg_match('/<button[^>]*data-cancel-withdrawal-confirmation[^>]*>'.($language==='en'?'Cancel':'Cancelar').'<\/button>/', $screen)===1);
}});
ic_test('Explicit empty public message and initial content remain empty',function(){$d=array('protocol_metadata'=>array('content_language'=>'en','public_messages'=>array('email_verified'=>'')));ic_assert(M::text($d,'email_verified')==='');$c=L\InitialScreen::defaults('en');$c['title_html']='';$c['authentication']['label_html']='';ic_assert(L\InitialScreen::normalize($c)['title_html']==='');});
}finally{
if($savedLanguage===null)delete_option('eipsi_forms_language');else update_option('eipsi_forms_language',$savedLanguage,false);
wp_set_current_user($ids['en']??$original);foreach($versions as $v)$owner->store->db->query($owner->store->prepare('DELETE FROM '.$owner->store->table('versions').' WHERE id=%s',$v['version_id']));foreach($assessments as $r)delete_option(A\Repository::PREFIX.$r['definition']['id']);foreach($studies as $s)$service->discard($s['id'],$s['revision']);if($library===null)delete_option(B\EmailLibrary::OPTION);else update_option(B\EmailLibrary::OPTION,$library,false);if($enabled===null)delete_option('eipsi_native_runtime_enabled');else update_option('eipsi_native_runtime_enabled',$enabled,false);wp_set_current_user($original);require_once ABSPATH.'wp-admin/includes/user.php';foreach($ids as $id)wp_delete_user($id);
}
echo "$tests tests, $failures failures\n";exit($failures?1:0);
